"OLAYLAR_ARKEOLOJI_HINT:-1599-01-01:0":{"b": ["Ուշ Հարապպյան շրջան. ավարտվում է", "c4c75773"], "d": ["Ուշ Հարապպյան շրջան (1900–1600 մ.թ.ա.), երբ քաղաքային կառույցները քայքայվեցին, բնակավայրերը ցրվեցին և տեղափոխվեցին արևելք/հարավ։", "11a3b7fd"]},
"OLAYLAR_ARKEOLOJI_HINT:-1899-01-01:0":{"b": ["Ուշ Հարապպյան շրջան. սկսվում է", "4574385e"], "d": ["Ուշ Հարապպյան շրջան (1900–1600 մ.թ.ա.), երբ քաղաքային կառույցները քայքայվեցին, բնակավայրերը ցրվեցին և տեղափոխվեցին արևելք/հարավ։", "11a3b7fd"]},
"OLAYLAR_ARKEOLOJI_HINT:-2549-01-01:0":{"b": ["Ռակհիգարհի. սկսվում է", "d92274bf"], "d": ["Հնդկաստանի ամենամեծ ինդոսյան բնակավայրը (մոտ 550 հա). ածուխի թվագրումները ընկնում են հասուն Հարապպյան շրջան, գերեզմանոցը հասուն շրջանի է։", "4b28acad"]},
"OLAYLAR_ARKEOLOJI_HINT:-2599-01-01:0":{"b": ["Հասուն Հարապպա (Ինդոսի քաղաքակրթության քաղաքային շրջան). սկսվում է", "8a8c9373"], "d": ["Քաղաքակիրթ դարձած Ինդոսի քաղաքակրթություն. ստանդարտ կշիռ-չափ, կնիքներ, պլանավորված քաղաքներ։ Շրջանը՝ 2600–1900 մ.թ.ա.. այնուհետև անցում ուշ Հարապպային։", "0d7d9bd6"]},
"OLAYLAR_ARKEOLOJI_HINT:-2899-01-01:0":{"b": ["Բուրզահոմ. սկսվում է", "fc757831"], "d": ["Քաշմիրի հովտի նեոլիթյան բնակավայր. փոսային տներ, թաղումներ (գանգահատություն). I շրջան՝ ոչ խեցեղենային, II՝ խեցեղենային, III՝ մեգալիթյան, IV՝ վաղ պատմական։", "749f13f5"]},
"OLAYLAR_ARKEOLOJI_HINT:-3199-01-01:0":{"b": ["Վաղ Հարապպյան շրջան (նախաքաղաքային / Early Harappan). սկսվում է", "06ca7d63"], "d": ["Քաղաքակրթությանը նախորդող՝ գյուղահեն Հարապպյան շրջան. հասուն շրջանում անցում է կատարվում քաղաքայնացմանը։ Ընդունված ժամանակագրումը. վաղ Հարապպա՝ 3200–2600 մ.թ.ա.։", "aa280065"]},
"OLAYLAR_ARKEOLOJI_HINT:-6433-01-01:0":{"b": ["Բհիռռանա. սկսվում է", "c7ce2ea6"], "d": ["Գհագգար-Հակրայի ավազանում «Հակրա փուլից» մինչև հասուն Հարապպա անընդհատ բնակավայր. պեղումների շարքը հիմք է Ինդոսից առաջ շատ հին բնակեցման պնդման համար։", "c4bd5284"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-10149-01-01:0":{"b": ["Մուրեյբետ՝ սկսվում է", "36f270da"], "d": ["Միջին Եփրատի բնակավայրերի հաջորդականություն՝ ուշ նատուֆյանից մինչև խիամյան, մուրեյբեթյան և վաղ/միջին PPNB. խիամյանի սահմանման տեղավայրը։", "2701ec22"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-11219-01-01:0":{"b": ["Աբու Հուրեյրա (Abu Hureyra)՝ սկսվում է", "2bdf51da"], "d": ["Եփրատի հովտում գտնվող էպիպալեոլիթյան որսորդ-հավաքիչների գյուղ. հետագայում ընդհատումներով նեոլիթյան (PPNB) բնակեցում՝ 2A (~7760-7440) և 2B (~7400-7100 մ.թ.ա.)։", "4c80e6fa"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-12649-01-01:0":{"b": ["Նատուֆյան մշակույթ՝ սկսվում է", "676e59ea"], "d": ["Ուշ էպիպալեոլիթ. մեծ բազա-ճամբար, քարե կառույցներ, թաղումներ. Շուբայկա 1-ում 27 AMS թվագրում՝ առաջին բնակեցում ~14,600-14,200 cal BP, լքում ~900 տարի, կրկին 13,300-13,000 և ~12,380-11,500 cal BP (2σ)։", "7774880e"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-6699-01-01:0":{"b": ["Այն Ղազալ (‘Ain Ghazal)՝ ավարտվում է", "72de216d"], "d": ["Հորդանանի մեծ նեոլիթյան բնակավայր՝ միջին-ուշ PPNB-ից մինչև PPNC. ~7600-7500-ին կարճ ընդմիջման վերաբերյալ պնդումը AMS-ով (7607-7531 cal BCE) կասկածի տակ է դրվել։", "0e7e6684"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-6749-01-01:0":{"b": ["Կֆար ՀաՀորեշ՝ ավարտվում է", "3dd4b264"], "d": ["Հարավային Լևանտի վաղ-ուշ PPNB-ի ծիսական/թաղման կենտրոն (ոչ բնակավայր). այծերի կառավարման անցման շրջան։", "d4fd3a60"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-6749-01-01:1":{"b": ["PPNC (ուշ PPNB) — Հարավային Լևանտ՝ սկսվում է", "4a371d7d"], "d": ["Հարավային Լևանտում ուշ PPNB (PPNC)՝ ~8,700-8,350 cal BP. այնուհետև խեցեղենով նեոլիթ՝ 8,350-7,450 cal BP։", "de5ba8e0"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-7099-01-01:0":{"b": ["Աբու Հուրեյրա (Abu Hureyra)՝ ավարտվում է", "8dbe0277"], "d": ["Եփրատի հովտում գտնվող էպիպալեոլիթյան որսորդ-հավաքիչների գյուղ. հետագայում ընդհատումներով նեոլիթյան (PPNB) բնակեցում՝ 2A (~7760-7440) և 2B (~7400-7100 մ.թ.ա.)։", "4c80e6fa"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-7139-01-01:0":{"b": ["Չայոնյու Թեփեսի՝ ավարտվում է", "35e97982"], "d": ["Ախեցեղեն նեոլիթ. կլոր կառույցի, ցանցաձև, ջրանցքներով, սալապատ, խցիկավոր և լայնասենյակ փուլեր. վաղ նեոլիթի վերջին շերտը՝ ~7140-6820։", "cab279f2"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-7499-01-01:0":{"b": ["Բաջա (Ba‘ja)՝ սկսվում է", "f9cce737"], "d": ["Հարավային Հորդանանի ուշ PPNB-ի լեռնային բնակավայր. թաղման (Loc. C10:408) 14C՝ 7071-6684 cal BCE (%95.4)։", "aee5092d"]},
"OLAYLAR_ARKEOLOJI_LEVANT_ANADOLU:-7599-01-01:0":{"b": ["Նևալը Չորի՝ ավարտվում է", "473f1ded"], "d": ["Վերին Եփրատի վաղ-միջին PPNB-ի բնակավայր. հետագայում վերաբնակեցվել է Հալաֆի, վաղ բրոնզի I, երկաթի դարի և հռոմեական շրջաններում։", "b371b37f"]},
