"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2499-01-01:0":{"b": ["Կերմայի (Քուշի) թագավորություն/մշակույթ. սկսվում է", "f7cdc981"], "d": ["Երրորդ սահանքից ներքև Կերմա կենտրոնով նուբիական թագավորություն. անցնելով Հին Կերմա (~2500), Միջին և Դասական Կերմա փուլերով՝ ավարտվում է մ.թ.ա. ~1450-ին։ Honegger 2005. 'Kerma Classique (vers 1500 av. J.-C.)' պաշարված բնակավայր։", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2662-01-01:0":{"b": ["Հին թագավորություն (բուրգերի դարաշրջան). սկսվում է", "9e3a1499"], "d": ["Բուրգերի դարաշրջանի թագավորություն. ըստ Erdil և ուրիշների 2025-ի՝ ՀԹ-ի սկիզբը մ.թ.ա. ~2698–2629 է (95%), անցումը Առաջին միջանկյալ շրջանին՝ մ.թ.ա. ~2283–2204 (95%)։ «Low» ժամանակագրությունն այս միջակայքում այլևս չի աջակցվում։", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3125-01-01:0":{"b": ["Նակադայի (Naqada) մշակույթ. ավարտվում է", "a6d98d7b"], "d": ["Վերին Եգիպտոսի Բադարիից հետո նախադինաստիական մշակույթ. ընդգրկում է Նակադա I-III փուլերը, Նակադա IIIC-ում I հարստությամբ (Ահա) հասնում է քաղաքական միասնության։", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3499-01-01:0":{"b": ["Նախա-Կերմա (Pre-Kerma) մշակույթ. սկսվում է", "35f09768"], "d": ["Կերմայի շրջանում (Դոնգոլայի բազուկ / Նեղոսի երրորդ սահանքից ներքև) նեոլիթից Կերմային անցնող, գյուղատնտեսական պահեստային փոսերով և վաղ սոցիալական բարդությամբ մշակույթ։", "f9a036cb"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3755-01-01:0":{"b": ["Նակադայի (Naqada) մշակույթ. սկսվում է", "1960a726"], "d": ["Վերին Եգիպտոսի Բադարիից հետո նախադինաստիական մշակույթ. ընդգրկում է Նակադա I-III փուլերը, Նակադա IIIC-ում I հարստությամբ (Ահա) հասնում է քաղաքական միասնության։", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3949-01-01:0":{"b": ["Տակարկորիի ժայռային ապաստարան (Տադրարտ Ակակուս). ավարտվում է", "845c6a70"], "d": ["Ժայռային ապաստարան Լիբիայի Ֆեցանում՝ Տադրարտ Ակակուսում. ուշ Ակակուսի որսորդ-հավաքչ-ձկնորսներից (LA1 առաջին բնակեցում) մինչև վաղ, միջին, ուշ հովվական հովիվները ձգվող անընդհատ շերտագրություն (կանաչ Սահարա)։", "29888604"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4699-01-01:0":{"b": ["Էշ-Շահեյնաբի (Shaheinab) նեոլիթ. սկսվում է", "7a9cfd9c"], "d": ["Կենտրոնական Սուդանում Նեղոսի մոտ նեոլիթյան բնակավայր (ընտանի կենդանիներ, խեցեղեն, դուր/gouge). որպես տիպային վայր սահմանում է «Շահեյնաբի նեոլիթը»։ Մշակույթի ընդհանուր միջակայքը՝ 5000–3800 BCE։", "cd4d3a3c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4849-01-01:0":{"b": ["Ֆայումի (Կարուն լճի շրջակայք) հոլոցենյան բնակեցում. ավարտվում է", "53ff4e34"], "d": ["Ֆայումում մ.թ.ա. ~7350-ից սկսած հոլոցենյան ձկնորս-որսորդների բնակեցում. ընտանի բույսեր-կենդանիներ մոտ մ.թ.ա. 5400-ից. Kom K/W նեոլիթյան բնակավայրերը՝ մ.թ.ա. 4850–4250։", "a016950f"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4999-01-01:0":{"b": ["Վաղ Խարտում (Խարտումի մեզոլիթ). ավարտվում է", "89b30a20"], "d": ["Կենտրոնական Սուդանում Նեղոսի ափին խեցեղենով (ալիքաձև գիծ) որսորդ-հավաքչ-ձկնորսների մեզոլիթ. Արքելը անվանել է 'Khartoum Mesolithic' / 'Early Khartoum'։", "7c5ed92c"]},
