"OLAYLAR_ARKEOLOJI_ZINCIR:-2549-01-01:0":{"b": ["Մարի. սկսվում է Մարի քաղաք-թագավորության (Մարի II, վաղ դինաստիական-Աքքադ) շրջանը", "36bcd311"], "d": ["Մարի. սկսվում է Մարի քաղաք-թագավորության (Մարի II, վաղ դինաստիական-Աքքադ) շրջանը։ Այս թվականը առանձին իրադարձություն չէ, այն ցույց է տալիս այս շրջանի սկիզբը. մանրամասներն ու աղբյուրները ներկայացված են ստորև։", "160e9689"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0009-01-10:0":{"b": ["Վան Մանը գահ բարձրացավ. Դունհուանը և Չժանյեն (Գանչժոու) Արևմտյան Հանից անցան անտեր միջակայքի", "f989b38a"], "d": ["Վան Մանը Հանի Բարձր տաճարում ընդունեց ոսկե արկղի կտակը, բարձրացավ գահ և հարստությունն անվանեց Սին. ավարտվեց Արևմտյան Հանը։ Քանի որ Հեսիի միջանցքի Դունհուանի և Չժանյեի՝ Սինի շրջանին վերաբերող տիրապետությունը աղբյուրում գրված չէ, այդ կետերն անցնում են անտեր միջակայքի (հայտարարված բացթողում)։ Չանանը ուղղակիորեն անցավ Սինին (առանձին հոդված)։", "ab9b1654"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0023-01-01:0":{"b": ["Լոյան, Սիան (Չանան). անտեր միջակայք → Գենշիի վարչակարգ (Սուան Հան / Լյուլին)", "1b17050e"], "d": ["Լոյան, Սիան (Չանան) կետերում տիրապետությունը անտեր միջակայքից անցնում է Գենշիի վարչակարգին (Սուան Հան / Լյուլին)։ Աղբյուրի անցման տեղեկությունը. Hou Han shu 11 (Լյու Սուան). Չանանում ապստամբություն Մանի դեմ. 9-րդ ամսին Գունբին Ցզյուն Մանին սպանեց Ցզյանթայում. Գենշին գնաց Լոյան, Շենտու Ցզյանը/Լի Սունը Չանանից սուրհանդակ ուղարկեցին, 2-րդ տարում (24) 2-րդ ամսին Գենշին Լոյանից շարժվեց արևմուտք (Չանան)։ Վերջին ծայրը. Hou Han shu 1a, Ցզյանու 1, 9-րդ ամիս. Չիմեյը մտավ Չանան, Գենշին փախավ Գաոլին։", "c2939213"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0025-01-01:0":{"b": ["Չենդու (Chengdu). անտեր միջակայք → Չենցզյա (成家, Գունսուն Շու)", "d4495a48"], "d": ["Չենդու (Chengdu) կետերում տիրապետությունը անտեր միջակայքից անցնում է Չենցզյային (成家, Գունսուն Շու)։ Աղբյուրի անցման տեղեկությունը. Hou Han shu 13 (Գունսուն Շու). Գենշիի շրջանում դարձավ «Շու Վան» և Չենդուն դարձրեց մայրաքաղաք. Ցզյանու 1 (մ.թ. 25) 4-րդ ամսին հռչակեց իրեն կայսր. Ցզյանու 12-ին՝ վախճանը (Ու Հանի արշավանքը, Չենդուի պաշարումը)։", "1480666e"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0025-01-01:1":{"b": ["Սիան (Չանան). սկսվում է Կարմիր Հոնքերի վարչակարգի (Ցզյանշի) շրջանը", "636e1d36"], "d": ["Սիան (Չանան). սկսվում է Կարմիր Հոնքերի վարչակարգի (Ցզյանշի) շրջանը։ Այս թվականը առանձին իրադարձություն չէ, այն ցույց է տալիս այս շրջանի սկիզբը. մանրամասներն ու աղբյուրները ներկայացված են ստորև։", "818c9b14"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0027-01-01:0":{"b": ["Սիան (Չանան). Կարմիր Հոնքերի վարչակարգ (Ցզյանշի) → անտեր միջակայք", "eff30d89"], "d": ["Սիան (Չանան) կետերում տիրապետությունը Կարմիր Հոնքերի վարչակարգից (Ցզյանշի) անցնում է անտեր միջակայքի։ Աղբյուրի անցման տեղեկությունը. Hou Han shu 1a, Ցզյանու 1. Չիմեյը մտավ Չանան, այրեց պալատը. նույն ամսին Դեն Յուն մտավ Չանան և 11 կայսրերի հուշատախտակները տարավ Գաո Մյաո (Հանի կարճատև մուտք)։ Չիմեյի դուրս գալը Չանանից (քարտ t=0027) այս փուլում չի կարդացվել։", "a5923e55"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0036-01-01:0":{"b": ["Չենդու (Chengdu). Չենցզյա (成家, Գունսուն Շու) → անտեր միջակայք", "f7bf9766"], "d": ["Չենդու (Chengdu) կետերում տիրապետությունը Չենցզյայից (成家, Գունսուն Շու) անցնում է անտեր միջակայքի։ Աղբյուրի անցման տեղեկությունը. Sanguozhi 32 (Xianzhu zhuan). Լյու Բեյը տասնյակ օրեր պաշարեց Չենդուն, Լյու Չժանը հանձնվեց (Ցզյանան 19 = 214 վերնագիր). Չժանու 1-ին (221) դարձավ կայսր։ Վերջը. Sanguozhi 28 (Դեն Այ). Լյու Շանը, ուղարկելով կայսերական կնիքը, հանձնվեց, Այը մտավ Չենդու, Լյու Շանը դուրս եկավ իշխանների և ավագանու հետ։", "93f5b44c"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0106-01-01:0":{"b": ["Պետրա. Նաբաթեական թագավորություն → Հռոմեական կայսրություն (պրինցիպատ-դոմինատ, միասնական)", "d1ea028d"], "d": ["Պետրա կետերում տիրապետությունը Նաբաթեական թագավորությունից անցնում է Հռոմեական կայսրությանը (պրինցիպատ-դոմինատ, միասնական)։ Աղբյուրի անցման տեղեկությունը. նույն աղբյուրը", "e056ba4b"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:0220-01-01:0":{"b": ["Լոյան. ավարտվում է Արևելյան Հան հարստության շրջանը", "777e18ad"], "d": ["Լոյան. ավարտվում է Արևելյան Հան հարստության շրջանը։ Այս թվականը առանձին իրադարձություն չէ, այն ցույց է տալիս այս շրջանի ավարտը. մանրամասներն ու աղբյուրները ներկայացված են ստորև։", "377d50de"]},
